'use client';
import React from 'react';
// Bare imports are stripped by the bundle compiler, so this resolves to the
// window global there; in an ESM consumer it resolves normally. Both work.
import ReactDOM from 'react-dom';
import { injectEfCss, useIsoLayoutEffect } from '../forms/Button.jsx';
const CSS = `
.ef-portal{display:contents}
`;

const noopSubscribe = () => () => {};
const onClient = () => true;
const onServer = () => false;
/**
 * False on the server and during hydration, true for every other client render.
 *
 * A Portal renders nothing on the server, so one mounted while React hydrates
 * server HTML is a mismatch. Owners gate on this instead of deferring Portal
 * itself: Toaster renders its portal only once this is true, and each overlay
 * root treats itself as closed until then (`useHydrated() && open`), so an
 * overlay open on first load opens right after hydration and its focus and
 * placement effects, keyed on open, run with the panel present.
 */
export function useHydrated() {
  return React.useSyncExternalStore(noopSubscribe, onClient, onServer);
}

/**
 * Renders children into document.body (or `container`).
 *
 * Every floating surface needs this. An overlay positioned inside its trigger's
 * subtree is clipped by the first ancestor with overflow:auto|hidden — which in
 * practice is the scrolling table, drawer, or card it was opened from.
 */
export function Portal({ children, container }) {
  injectEfCss('ef-css-portal', CSS);
  const hostRef = React.useRef(null);
  if (hostRef.current === null && typeof document !== 'undefined') {
    hostRef.current = document.createElement('div');
    hostRef.current.className = 'ef-portal';
  }
  // Children mount into the host on the first render, while it is still detached,
  // and this layout effect attaches it before paint. Gating the render on a
  // "mounted" state instead would leave the panel absent when the parent measures
  // it for placement, which puts every anchored overlay at the viewport origin.
  useIsoLayoutEffect(() => {
    const host = hostRef.current;
    if (!host) return;
    const parent = container || document.body;
    parent.appendChild(host);
    // StrictMode (on by default in Next.js dev) runs the cleanup and this effect
    // again right after mount. Detaching the host blurs whatever a dialog just
    // focused inside it, so put that focus back once the host is attached again.
    const refocus = host.__efRefocus;
    host.__efRefocus = null;
    if (refocus && refocus.isConnected && host.contains(refocus)
      && (document.activeElement === document.body || document.activeElement === null)) {
      refocus.focus({ preventScroll: true });
    }
    return () => {
      const active = document.activeElement;
      host.__efRefocus = active && host.contains(active) ? active : null;
      if (host.parentNode) host.parentNode.removeChild(host);
    };
  }, [container]);
  if (!hostRef.current) return null;
  return ReactDOM.createPortal(children, hostRef.current);
}

/**
 * Position a portaled panel against its anchor, in viewport coordinates.
 *
 * Flips to the opposite side when the preferred one would overflow, then shifts
 * along the cross axis to stay on screen. Returns { style, side } — the panel is
 * hidden for the first frame so the measurement never flashes, and `side` is the
 * placement actually resolved, which a caller drawing an arrow has to know.
 *
 * Not exported on the namespace — it is a building block for the overlay
 * components, and is only useful with a panel ref you already control.
 */
export function useAnchoredStyle(anchorRef, panelRef, { open, placement = 'bottom', align = 'start', offset = 6, crossOffset = 0, matchWidth = false } = {}) {
  const [state, setState] = React.useState({
    // `right`/`bottom` are pinned to auto from the very first frame. A panel
    // whose class also sets `right: 0` (every align="right" menu) would
    // otherwise be laid out with both edges pinned, stretch to the full
    // viewport, and get measured at that width — so the clamp below shoved it
    // against the left edge instead of under its trigger.
    style: { position: 'fixed', top: 0, left: 0, right: 'auto', bottom: 'auto', visibility: 'hidden' },
    side: placement,
  });
  useIsoLayoutEffect(() => {
    if (!open) {
      setState(s => (s.style.visibility === 'hidden' ? s : { ...s, style: { ...s.style, visibility: 'hidden' } }));
      return;
    }
    const place = () => {
      const anchor = anchorRef.current;
      const panel = panelRef.current;
      if (!anchor || !panel) return;
      const a = anchor.getBoundingClientRect();
      const p = panel.getBoundingClientRect();
      const vw = document.documentElement.clientWidth;
      const vh = document.documentElement.clientHeight;
      const edge = 8;

      const horizontal = placement === 'left' || placement === 'right';
      // start/end are logical: in a right-to-left layout "start" is the anchor's right edge
      const dirNode = anchor.closest('[dir]');
      const rtl = (dirNode ? dirNode.getAttribute('dir') : document.documentElement.dir) === 'rtl';
      const inline = !horizontal && rtl ? (align === 'start' ? 'end' : align === 'end' ? 'start' : align) : align;
      const roomAfter = horizontal ? vw - a.right - offset : vh - a.bottom - offset;
      const roomBefore = horizontal ? a.left - offset : a.top - offset;
      const panelSize = horizontal ? p.width : p.height;
      const wantsBefore = placement === 'top' || placement === 'left';
      const beforeSide = horizontal ? 'left' : 'top';
      const afterSide = horizontal ? 'right' : 'bottom';
      const side = wantsBefore
        ? (roomBefore >= panelSize || roomBefore >= roomAfter ? beforeSide : afterSide)
        : (roomAfter >= panelSize || roomAfter >= roomBefore ? afterSide : beforeSide);

      // a width-matched panel (a listbox under its input) is measured at the
      // anchor's width, not its own, or the clamp below uses the wrong number
      const width = matchWidth ? a.width : p.width;
      let top;
      let left;
      if (horizontal) {
        left = side === 'right' ? a.right + offset : a.left - offset - width;
        top = align === 'end' ? a.bottom - p.height
          : align === 'center' ? a.top + a.height / 2 - p.height / 2
          : a.top;
        top += crossOffset;
      } else {
        top = side === 'bottom' ? a.bottom + offset : a.top - offset - p.height;
        left = inline === 'end' ? a.right - width
          : inline === 'center' ? a.left + a.width / 2 - width / 2
          : a.left;
        left += rtl ? -crossOffset : crossOffset;
      }

      left = Math.max(edge, Math.min(left, vw - width - edge));
      top = Math.max(edge, Math.min(top, vh - p.height - edge));

      const next = { position: 'fixed', top: Math.round(top), left: Math.round(left), right: 'auto', bottom: 'auto', visibility: 'visible' };
      if (matchWidth) next.width = Math.round(a.width);
      setState({ style: next, side });
    };
    place();
    // capture phase: any scrolling ancestor moves the anchor, not just the window
    window.addEventListener('scroll', place, true);
    window.addEventListener('resize', place);
    return () => {
      window.removeEventListener('scroll', place, true);
      window.removeEventListener('resize', place);
    };
  }, [open, placement, align, offset, crossOffset, matchWidth, anchorRef, panelRef]);
  return state;
}

export const escapeLayerContext = React.createContext(null);
const handledEscapes = new WeakSet();

/**
 * Escape dismisses the innermost open layer, and only that one.
 *
 * Every modal and popover used to listen on `document` for itself, so a
 * Popover inside a Dialog, or a Dialog inside a Dialog, closed together on one
 * key press. Layers rendered inside another layer's subtree register with it
 * through context (React context follows portals, the DOM does not), and a
 * layer with an open child leaves the key to the child. A layer whose caller
 * cancels the key (`preventDefault`) or that has no way out still consumes it.
 *
 * Returns the layer; wrap the layer's children in
 * `<escapeLayerContext.Provider value={layer}>`. Not exported on the namespace.
 */
export function useEscapeLayer(active, onEscape) {
  const parent = React.useContext(escapeLayerContext);
  const layerRef = React.useRef(null);
  if (layerRef.current === null) layerRef.current = { children: 0 };
  const handlerRef = React.useRef(onEscape);
  handlerRef.current = onEscape;
  React.useEffect(() => {
    if (!active) return;
    const layer = layerRef.current;
    if (parent) parent.children += 1;
    const key = event => {
      if (event.key !== 'Escape' || event.defaultPrevented || layer.children > 0 || handledEscapes.has(event)) return;
      handledEscapes.add(event);
      handlerRef.current?.(event);
    };
    document.addEventListener('keydown', key);
    return () => {
      if (parent) parent.children -= 1;
      document.removeEventListener('keydown', key);
    };
  }, [active, parent]);
  return layerRef.current;
}

let scrollLocks = 0;
let savedOverflow = '';
/**
 * Keep the page behind a modal from scrolling. Counted, so a dialog opened
 * from a dialog does not restore scrolling when the inner one closes.
 */
export function useScrollLock(active) {
  React.useEffect(() => {
    if (!active) return;
    if (scrollLocks === 0) {
      savedOverflow = document.body.style.overflow;
      document.body.style.overflow = 'hidden';
    }
    scrollLocks += 1;
    return () => {
      scrollLocks -= 1;
      if (scrollLocks === 0) document.body.style.overflow = savedOverflow;
    };
  }, [active]);
}

export interface PortalProps {
  children?: React.ReactNode;
  /** Where to mount. @default document.body */
  container?: HTMLElement;
}
/**
 * Render children outside the current DOM subtree so they cannot be clipped by
 * an ancestor's overflow. Used by every floating surface in the system.
 */
export declare function Portal(props: PortalProps): React.JSX.Element | null;
